import { useState } from "react";

const Jobseeker = () => {
  const [message, setMessage] = useState('');
  const [messageType, setMessageType] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [FirstName, setFirstName] = useState('');
  const [LastName, setLastName] = useState('');
    const [Gender, setGender] = useState('');
     const [ EmailAddress, setEmailAddress] = useState('');
     const [DateofBirth, setDateofBirth] = useState('');
  const [City, setCity] = useState('');
  const [Field, setField] = useState('');
const [WorkExperience, setWorkExperience] = useState('');
  const [UniversityCollege, setUniversityCollege] = useState('');
    const [GraduationYear, setGraduationYear] = useState('');
    const [CV, setCV] = useState('');
 
 const handleSubmit = (e) => {
    e.preventDefault();
   setMessage('');
   setMessageType('');
   setIsSubmitting(true);
    const Jobseeker = {FirstName,LastName,Gender, EmailAddress,DateofBirth,City,Field,WorkExperience,UniversityCollege,GraduationYear,CV};

    fetch('http://localhost:5000/Jobseekers/', {
      method: 'POST',
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(Jobseeker)
    })
    .then((response)=>{
      if(!response.ok){
        return response.json().then((data) => {
          throw new Error(data.message || "Failed to save Jobseeker");
        });
      }
      return response.json();
    })
    .then((data)=>{
      console.log("Jobseeker saved:",data);
      setMessage("Your registration was completed successfully.");
      setMessageType("success");
    })
    .catch((error)=>{
      console.log("Error:",error);
      setMessage(`Registration failed: ${error.message}`);
      setMessageType("error");
    })
    .finally(() => {
      setIsSubmitting(false);
    });
      
    }
 return (
    <div className="seeker">
      <h2>Create Your Jobseeker Account</h2>
      <p className="seeker-intro">Share your details and connect with your next opportunity.</p>
      {message && (
        <div className={`seeker-message ${messageType}`} role="alert">
          {message}
        </div>
      )}
      <form onSubmit={handleSubmit}>
        <label>First Name:</label>
        <input 
          type="text" 
          placeholder="Enter First Name"
          required 
          value={FirstName}
          onChange={(e) => setFirstName(e.target.value)}
        />
         <label>Last Name:</label>
        <input 
          type="text" 
          placeholder="Enter Last Name"
          required 
          value={LastName}
          onChange={(e) => setLastName(e.target.value)}
        />
         <label>Gender:</label>
        <select
          required
          value={Gender}
          onChange={(e) => setGender(e.target.value)}
        >
          <option value="Female">Female</option>
          <option value="Male">Male</option>
           </select>
        <label>Email Address:</label>
        <input 
          type="email" 
          placeholder="Enter Your Email Address"
          required 
          value={EmailAddress}
          onChange={(e) => setEmailAddress(e.target.value)}
        />
          <label>Date of Birth:</label>
        <input 
          type="Date" 
          required 
          value={DateofBirth}
          onChange={(e) => setDateofBirth(e.target.value)}
        />
        <label>City:</label>
        <select
          required
          value={City}
          onChange={(e) => setCity(e.target.value)}
        >
          <option value="Addiss Ababa">Addiss Ababa</option>
           <option value="Dire Dewa">Dire Dewa</option>
            <option value="Harar">Harar</option>
             <option value="Debrebirhan">Debrebirhan</option>
              <option value="Adigrat">Adigrat</option>
          <option value="Mekele">Mekele</option>
           <option value="Nazret">Nazret</option>
           </select>
            <label>Field:</label>
        <select
          required
          value={Field}
          onChange={(e) => setField(e.target.value)}
        >
          <option value="Doctor">Doctor</option>
           <option value="Nurse">Nurse</option>
            <option value="Software Developer">Software Developer</option>
             <option value="IT Specialist"> IT Specialist</option>
              <option value="Civil Engineer">Civil Engineer</option>
          <option value="Mechanical Engineer">Mechanical Engineer</option>
           <option value="Teacher">Teacher</option>
           <option value="Business Manager">Business Manager</option>
           <option value="Lawyer">Lawyer</option>
           <option value="Pharmacist">Pharmacist</option>
           <option value="Banker">Banker</option>
           <option value="Graphic Designer">Graphic Designer</option>
           <option value="Digital Marketer">Digital Marketer</option>
           <option value="Driver">Driver</option>
           <option value="Chef">Chef</option>
           <option value="Architect">Architect</option>
           <option value="Journalist">Journalistr</option>
           </select>

            <label>Work Experience:</label>
        <input 
          type="text" 
          required 
          value={WorkExperience}
          onChange={(e) => setWorkExperience(e.target.value)}
        />
 <label>University/Collage:</label>
        <input 
          type="text" 
          required 
          value={UniversityCollege}
          onChange={(e) => setUniversityCollege(e.target.value)}
        />
         <label>GraduationYear:</label>
        <input 
          type="number" 
          min="1900"
          max={new Date().getFullYear()}
          required 
          value={GraduationYear}
          onChange={(e) => setGraduationYear(e.target.value)}
        />
       <label>CV</label>
        <textarea 
        required
        placeholder="Enter your CV letter"
        value={CV}
          onChange={(e) => setCV(e.target.value)}></textarea>
      <br></br>
     <button type="submit" disabled={isSubmitting}>
       {isSubmitting ? "Submitting..." : "Submit"}
     </button>
      </form>
    </div>
  );
}

export default Jobseeker ;
